rows=[];items=[]
def item(n,kind,scans,lines,words,statement,reconstruction,check='agrees',reason='',verdict='kept',extra=None):
    ident=f'SA18-{45000+n}'
    obj=dict(id=ident,sources=[f'MPL_45_033-080#{n}'],kind=kind,cote='45',scans=scans,lines=[f'{PRO}:{lines}'],his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason)
    if extra: obj['lines']+=extra
    items.append(obj);rows.append(dict(entry_id=obj['sources'][0],item_id=ident,verdict=verdict,reason=reason))
